class TenantPool {
  constructor() {
    this.credits = new Map(); // tenantId -> credits
    this.queues = new Map(); // tenantId -> queue
  }
  tryConsume(tenantId, ms) {
    const c = this.credits.get(tenantId) || 0;
    if (c + ms <= budgetFor(tenantId)) {
      this.credits.set(tenantId, c + ms);
      return true;
    }
    return false;
  }
}
```

